/**
 * Source of the graphic runtime that is embedded in every exported graphic (and runs the editor canvas).
 *
 * It is plain, dependency-free JavaScript (an ES module with a default-exported Web Component). The exporter
 * replaces the PROJECT placeholder with the project JSON. Kept as a string so it can be written verbatim into
 * the package; it intentionally uses no template literals.
 */
export const PROJECT_PLACEHOLDER = '/*__OGP_PROJECT__*/null';

export const RUNTIME_SOURCE = String.raw`/**
 * OGraf graphic generated by the OGraf GFX Platform editor.
 * Self-contained Web Component (Shadow DOM + Web Animations API), no dependencies.
 */
const PROJECT = /*__OGP_PROJECT__*/null;

const TOKEN = /\{([A-Za-z_][A-Za-z0-9_]*)(?::([a-z0-9]+))?\}/g;

function resolveAsset(src) {
  if (!src) return '';
  if (/^(https?:|data:|blob:|\/)/.test(src)) return src;
  try { return new URL(src, import.meta.url).href; } catch (e) { return src; }
}

function isClock(v) { return v !== null && typeof v === 'object' && v.$type === 'clock'; }

function clockElapsed(c, now) {
  var anchor = typeof c.anchorLocalMs === 'number' ? c.anchorLocalMs : c.anchorServerMs;
  var base = Number(c.elapsedAtAnchorMs) || 0;
  return Math.max(0, base + (c.running && typeof anchor === 'number' ? Math.max(0, now - anchor) : 0));
}

function mmss(ms) {
  var t = Math.floor(Math.max(0, ms) / 1000);
  var m = Math.floor(t / 60), s = t % 60;
  return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
}

/** {clock} -> 23:41 (frozen at the limit), {clock:stoppage} -> +1:23 or '', {clock:minute} -> 24' / 45+2' */
function clockText(c, fmt, now) {
  var e = clockElapsed(c, now);
  var limit = typeof c.limitMs === 'number' ? c.limitMs : null;
  if (fmt === 'stoppage') return limit !== null && e > limit ? '+' + mmss(e - limit).replace(/^0/, '') : '';
  if (fmt === 'minute') {
    var min = Math.floor(e / 60000) + 1;
    if (limit !== null) {
      var lm = Math.round(limit / 60000);
      if (min > lm) return lm + '+' + (min - lm) + "'";
    }
    return min + "'";
  }
  return mmss(limit !== null && e > limit ? limit : e);
}

function renderText(text, data, now) {
  return String(text || '').replace(TOKEN, function (_, key, fmt) {
    var v = data[key];
    if (isClock(v)) return clockText(v, fmt, now);
    if (v === undefined || v === null) return '';
    if (fmt === 'upper') return String(v).toUpperCase();
    if (fmt === 'lower') return String(v).toLowerCase();
    if (fmt === 'pad2') return String(v).padStart(2, '0');
    return String(v);
  });
}

function usesClock(text, data) {
  var found = false;
  String(text || '').replace(TOKEN, function (_, key) { if (isClock(data[key])) found = true; return ''; });
  return found;
}

function walk(layers, fn) {
  for (var i = 0; i < layers.length; i++) {
    fn(layers[i]);
    if (layers[i].type === 'group') walk(layers[i].children, fn);
  }
}

/* ---------------- timeline maths (same as editor-core/timeline.ts) ---------------- */
var CURVES = {
  'ease-in': [0.7, 0, 0.84, 0],
  'ease-out': [0.16, 1, 0.3, 1],
  'ease-in-out': [0.65, 0, 0.35, 1],
  smooth: [0.16, 1, 0.3, 1],
  back: [0.34, 1.56, 0.64, 1]
};
var PROPS = ['x', 'y', 'scale', 'opacity', 'rotation', 'maskL', 'maskR', 'maskT', 'maskB'];

function cubicBezier(x1, y1, x2, y2, x) {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  var cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  var cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  function sx(t) { return ((ax * t + bx) * t + cx) * t; }
  var t = x, i;
  for (i = 0; i < 8; i++) {
    var err = sx(t) - x;
    if (Math.abs(err) < 1e-6) break;
    var d = (3 * ax * t + 2 * bx) * t + cx;
    if (Math.abs(d) < 1e-6) break;
    t -= err / d;
  }
  if (t < 0 || t > 1 || Math.abs(sx(t) - x) > 1e-4) {
    var lo = 0, hi = 1;
    t = x;
    for (i = 0; i < 40; i++) {
      var v = sx(t);
      if (Math.abs(v - x) < 1e-6) break;
      if (v < x) lo = t; else hi = t;
      t = (lo + hi) / 2;
    }
  }
  return ((ay * t + by) * t + cy) * t;
}

function ease(e, p) {
  if (e === 'linear') return p;
  if (e === 'hold') return p >= 1 ? 1 : 0;
  var c = CURVES[e] || CURVES.smooth;
  return cubicBezier(c[0], c[1], c[2], c[3], p);
}

function staticValue(l, prop) {
  var v = l[prop];
  if (typeof v === 'number') return v;
  return prop === 'scale' || prop === 'opacity' ? 1 : 0;
}

function sortedTrack(l, prop) {
  var tr = l.tracks && l.tracks[prop];
  if (!tr || !tr.length) return null;
  if (!tr.__sorted) { tr = tr.slice().sort(function (a, b) { return a.t - b.t; }); }
  return tr;
}

function valueAt(l, prop, t) {
  var tr = sortedTrack(l, prop);
  if (!tr) return staticValue(l, prop);
  if (t <= tr[0].t) return tr[0].v;
  var last = tr[tr.length - 1];
  if (t >= last.t) return last.v;
  for (var i = 0; i < tr.length - 1; i++) {
    var a = tr[i], b = tr[i + 1];
    if (t >= a.t && t <= b.t) {
      if (b.t === a.t) return b.v;
      return a.v + (b.v - a.v) * ease(a.ease, (t - a.t) / (b.t - a.t));
    }
  }
  return last.v;
}

function stateAt(l, t) {
  var s = {};
  for (var i = 0; i < PROPS.length; i++) s[PROPS[i]] = valueAt(l, PROPS[i], t);
  return s;
}

function cssOf(l, s) {
  return {
    transform: 'translate(' + (s.x - l.x) + 'px, ' + (s.y - l.y) + 'px) rotate(' + s.rotation + 'deg) scale(' + s.scale + ')',
    opacity: String(Math.max(0, Math.min(1, s.opacity))),
    clipPath: 'inset(' + s.maskT + '% ' + s.maskR + '% ' + s.maskB + '% ' + s.maskL + '%)'
  };
}

function normTimeline(tl) {
  var steps = (tl && tl.steps && tl.steps.length ? tl.steps.slice() : [0]).sort(function (a, b) { return a - b; });
  var out = Math.max(steps[steps.length - 1], (tl && tl.out) || 0);
  return { steps: steps, out: out, duration: Math.max(out, (tl && tl.duration) || 0) };
}

/** For tests and tools; OGraf only uses the default export. */
export const __ogpRuntime = { stateAt: stateAt, valueAt: valueAt, ease: ease, cssOf: cssOf };

var CSS = [
  ':host { display: block; position: absolute; inset: 0; overflow: hidden; pointer-events: none; }',
  '* { box-sizing: border-box; margin: 0; padding: 0; }',
  '.canvas { position: absolute; left: 0; top: 0; transform-origin: 0 0; }',
  '.stage { position: absolute; inset: 0; visibility: hidden; }',
  '.stage.on { visibility: visible; }',
  '.L { position: absolute; transform-origin: 50% 50%; }',
  '.V { position: absolute; inset: 0; }',
  '.T { position: absolute; inset: 0; display: flex; overflow: visible; }',
  '.T span { display: block; width: 100%; }',
  '.I { position: absolute; inset: 0; width: 100%; height: 100%; }',
  '.hide { display: none !important; }'
].join('\n');

export default class OGrafEditorGraphic extends HTMLElement {
  constructor() {
    super();
    this._root = this.attachShadow({ mode: 'open' });
    this._project = PROJECT;
    this._data = {};
    this._nodes = [];
    this._anims = new Set();
    this._visible = false;
    this._step = undefined;
    this._raf = 0;
    this._clockNodes = [];
  }

  // ------------------------------------------------------------- OGraf interface

  async load(params) {
    var p = params || {};
    this._data = Object.assign(this._defaults(), p.data || {});
    this._build();
    this._apply();
    await this._imagesReady();
    return { statusCode: 200 };
  }

  async dispose() {
    this._cancelAll();
    cancelAnimationFrame(this._raf);
    if (this._ro) this._ro.disconnect();
    this._root.innerHTML = '';
    return { statusCode: 200 };
  }

  async playAction(params) {
    var p = params || {};
    var tl = this._timeline();
    var count = tl.steps.length;
    var cur = this._step;
    var target = Number.isInteger(p.goto) && p.goto >= 0 ? p.goto : (cur === undefined ? -1 : cur) + (Number.isInteger(p.delta) ? p.delta : 1);
    if (target < 0) target = 0;
    if (target >= count) {
      await this._out(p.skipAnimation);
      return { statusCode: 200, currentStep: undefined };
    }
    this._step = target;
    if (cur === undefined || !this._visible) {
      // from the start state: play from 0 to the target step
      this._cancelAll();
      this._visible = true;
      this._applyStateAt(0);
      this._stage.classList.add('on');
      await this._playSegment(0, tl.steps[target], p.skipAnimation);
    } else if (target > cur) {
      await this._playSegment(tl.steps[cur], tl.steps[target], p.skipAnimation);
    } else if (target < cur) {
      // going back: a short transition from the current state to the state of that step
      await this._transitionTo(tl.steps[target], 400, p.skipAnimation);
    }
    return { statusCode: 200, currentStep: this._step === undefined ? undefined : this._step };
  }

  async stopAction(params) {
    await this._out((params || {}).skipAnimation);
    return { statusCode: 200 };
  }

  async updateAction(params) {
    var p = params || {};
    this._data = Object.assign({}, this._data, p.data || {});
    this._apply();
    return { statusCode: 200 };
  }

  async customAction(params) {
    return { statusCode: 404, statusMessage: 'Unknown custom action "' + ((params || {}).id) + '"' };
  }

  /**
   * Editor hook (vendor): replace project/data and show the state at "time" (ms on the timeline;
   * default: the first step) without animation.
   */
  v_ogpEdit(opts) {
    var o = opts || {};
    if (o.project) this._project = o.project;
    if (o.data) this._data = Object.assign(this._defaults(), o.data);
    this._cancelAll();
    this._build();
    this._apply();
    this._visible = o.shown !== false;
    this._step = this._visible ? 0 : undefined;
    this._applyStateAt(typeof o.time === 'number' ? o.time : this._timeline().steps[0]);
    this._stage.classList.toggle('on', this._visible);
  }

  /** Editor hook: show the state at time t (scrubbing). */
  v_ogpSeek(t) {
    this._cancelAll();
    this._applyStateAt(t);
    this._stage.classList.add('on');
  }

  /** Editor hook: play the timeline from t0 to t1 (preview). */
  v_ogpPlayRange(t0, t1) {
    this._cancelAll();
    this._applyStateAt(t0);
    this._stage.classList.add('on');
    return this._playSegment(t0, t1, false);
  }

  // ------------------------------------------------------------- building

  _defaults() {
    var out = {};
    var fields = (this._project && this._project.fields) || [];
    for (var i = 0; i < fields.length; i++) {
      var f = fields[i];
      if (f.type === 'clock') continue;
      if (f.default !== undefined) out[f.key] = f.default;
      else out[f.key] = f.type === 'boolean' ? false : f.type === 'number' || f.type === 'integer' ? 0 : '';
    }
    return out;
  }

  _build() {
    var pr = this._project || { width: 1920, height: 1080, layers: [] };
    this._root.innerHTML = '<style>' + CSS + '</style><div class="canvas"><div class="stage"></div></div>';
    this._canvas = this._root.querySelector('.canvas');
    this._stage = this._root.querySelector('.stage');
    this._canvas.style.width = pr.width + 'px';
    this._canvas.style.height = pr.height + 'px';
    this._nodes = [];
    for (var i = 0; i < pr.layers.length; i++) this._stage.appendChild(this._make(pr.layers[i]));
    if (this._visible) this._stage.classList.add('on');
    if (!this._ro) {
      var self = this;
      this._ro = new ResizeObserver(function () { self._fit(); });
      this._ro.observe(this);
    }
    this._fit();
  }

  _make(l) {
    var box = document.createElement('div');
    box.className = 'L';
    var vis = document.createElement('div');
    vis.className = 'V';
    box.appendChild(vis);
    var node = { l: l, box: box, vis: vis };
    if (l.type === 'text') {
      node.text = document.createElement('div');
      node.text.className = 'T';
      node.span = document.createElement('span');
      node.text.appendChild(node.span);
      vis.appendChild(node.text);
    } else if (l.type === 'image') {
      node.img = document.createElement('img');
      node.img.className = 'I';
      node.img.alt = '';
      vis.appendChild(node.img);
    } else if (l.type === 'group') {
      for (var i = 0; i < l.children.length; i++) vis.appendChild(this._make(l.children[i]));
    }
    this._nodes.push(node);
    return node.box;
  }

  _fit() {
    if (!this._canvas) return;
    var pr = this._project || { width: 1920, height: 1080 };
    var r = this.getBoundingClientRect();
    var s = Math.min((r.width || pr.width) / pr.width, (r.height || pr.height) / pr.height);
    this._canvas.style.transform = 'scale(' + s + ')';
  }

  // ------------------------------------------------------------- data -> DOM

  _apply() {
    var d = this._data;
    var now = Date.now();
    this._clockNodes = [];
    for (var i = 0; i < this._nodes.length; i++) {
      var n = this._nodes[i];
      var l = n.l;
      var b = l.bindings || {};
      var bs = n.box.style, vs = n.vis.style;
      bs.left = l.x + 'px'; bs.top = l.y + 'px'; bs.width = l.width + 'px'; bs.height = l.height + 'px';
      var shown = l.visible !== false && (b.visible ? Boolean(d[b.visible]) : true);
      n.box.classList.toggle('hide', !shown);
      if (l.type === 'shape') {
        var fill = b.fill && /^#[0-9a-f]{6}$/i.test(String(d[b.fill])) ? d[b.fill] : l.fill;
        vs.background = l.fill2 ? 'linear-gradient(' + l.gradientAngle + 'deg, ' + fill + ', ' + l.fill2 + ')' : fill;
        vs.borderRadius = l.shape === 'ellipse' ? '50%' : l.radius + 'px';
        vs.border = l.strokeWidth > 0 ? l.strokeWidth + 'px solid ' + l.strokeColor : '';
        vs.boxShadow = l.shadow ? '0 12px 28px rgba(0, 0, 0, 0.45)' : '';
      } else if (l.type === 'group') {
        vs.overflow = l.clip ? 'hidden' : 'visible';
      } else if (l.type === 'image') {
        var src = b.src ? d[b.src] : l.src;
        var url = resolveAsset(src);
        if (n.img.getAttribute('src') !== url) {
          if (url) n.img.setAttribute('src', url); else n.img.removeAttribute('src');
        }
        n.img.style.objectFit = l.fit;
        n.img.classList.toggle('hide', !url);
      } else if (l.type === 'text') {
        var color = b.color && /^#[0-9a-f]{6}$/i.test(String(d[b.color])) ? d[b.color] : l.color;
        var ts = n.text.style;
        ts.justifyContent = l.align === 'center' ? 'center' : l.align === 'right' ? 'flex-end' : 'flex-start';
        ts.alignItems = l.vAlign === 'top' ? 'flex-start' : l.vAlign === 'bottom' ? 'flex-end' : 'center';
        var ss = n.span.style;
        ss.fontFamily = l.fontFamily;
        ss.fontWeight = String(l.fontWeight);
        ss.fontStyle = l.italic ? 'italic' : 'normal';
        ss.textTransform = l.uppercase ? 'uppercase' : 'none';
        ss.color = color;
        ss.textAlign = l.align;
        ss.letterSpacing = l.letterSpacing + 'px';
        ss.lineHeight = String(l.lineHeight);
        ss.whiteSpace = l.shrinkToFit ? 'pre' : 'pre-wrap';
        ss.textShadow = l.shadow ? '0 3px 10px rgba(0, 0, 0, 0.55)' : '';
        ss.fontVariantNumeric = 'tabular-nums';
        this._setText(n, renderText(l.text, d, now));
        if (usesClock(l.text, d)) this._clockNodes.push(n);
      }
    }
    var self = this;
    cancelAnimationFrame(this._raf);
    if (this._clockNodes.length) {
      var tick = function () {
        self._raf = requestAnimationFrame(tick);
        var t = Date.now();
        for (var j = 0; j < self._clockNodes.length; j++) self._setText(self._clockNodes[j], renderText(self._clockNodes[j].l.text, self._data, t));
      };
      this._raf = requestAnimationFrame(tick);
    }
  }

  _setText(n, value) {
    if (n.lastText === value) return;
    n.lastText = value;
    var l = n.l;
    n.span.textContent = value;
    n.span.style.fontSize = l.fontSize + 'px';
    if (l.shrinkToFit && value) {
      var w = n.span.scrollWidth;
      if (w > l.width) n.span.style.fontSize = Math.max(l.fontSize * 0.4, Math.floor(l.fontSize * l.width / w)) + 'px';
    }
  }

  _imagesReady() {
    var imgs = [];
    for (var i = 0; i < this._nodes.length; i++) if (this._nodes[i].img && this._nodes[i].img.getAttribute('src')) imgs.push(this._nodes[i].img);
    var waits = imgs.map(function (img) {
      return img.complete ? Promise.resolve() : new Promise(function (r) { img.addEventListener('load', r, { once: true }); img.addEventListener('error', r, { once: true }); });
    });
    return Promise.race([Promise.all(waits), new Promise(function (r) { setTimeout(r, 2000); })]);
  }

  // ------------------------------------------------------------- animation

  _timeline() {
    return normTimeline(this._project && this._project.timeline);
  }

  _applyStateAt(t) {
    for (var i = 0; i < this._nodes.length; i++) {
      var n = this._nodes[i];
      var c = cssOf(n.l, stateAt(n.l, t));
      var st = n.box.style;
      st.transform = c.transform;
      st.opacity = c.opacity;
      st.clipPath = c.clipPath;
    }
  }

  /** Plays the timeline from t0 to t1, starting every layer from its current state (no jumps when interrupting). */
  async _playSegment(t0, t1, skip) {
    this._cancelAll();
    var dur = t1 - t0;
    if (skip || dur <= 0 || document.visibilityState === 'hidden') {
      this._applyStateAt(t1);
      return;
    }
    var samples = Math.max(2, Math.ceil(dur / (1000 / 60)));
    var runs = [];
    for (var i = 0; i < this._nodes.length; i++) {
      var n = this._nodes[i];
      var frames = [];
      var constant = true;
      var first = null;
      for (var k = 1; k <= samples; k++) {
        var c = cssOf(n.l, stateAt(n.l, t0 + dur * k / samples));
        var key = c.transform + c.opacity + c.clipPath;
        if (first === null) first = key; else if (key !== first) constant = false;
        frames.push({ offset: k / samples, transform: c.transform, opacity: c.opacity, clipPath: c.clipPath });
      }
      var start = cssOf(n.l, stateAt(n.l, t0));
      if (constant && start.transform + start.opacity + start.clipPath === first) {
        // nothing moves in this segment for this layer: make sure it is at its target state
        var s0 = n.box.style;
        var end = frames[frames.length - 1];
        if (s0.transform !== end.transform || s0.opacity !== end.opacity || s0.clipPath !== end.clipPath) {
          s0.transform = end.transform; s0.opacity = end.opacity; s0.clipPath = end.clipPath;
        }
        continue;
      }
      // no offset-0 keyframe: the animation starts from the current (committed) state
      runs.push(this._run(n.box, frames, { duration: dur, delay: 0, easing: 'linear' }, false));
    }
    await Promise.all(runs);
  }

  async _transitionTo(t, duration, skip) {
    this._cancelAll();
    if (skip || document.visibilityState === 'hidden') return this._applyStateAt(t);
    var runs = [];
    for (var i = 0; i < this._nodes.length; i++) {
      var n = this._nodes[i];
      var c = cssOf(n.l, stateAt(n.l, t));
      runs.push(this._run(n.box, [{ offset: 1, transform: c.transform, opacity: c.opacity, clipPath: c.clipPath }], { duration: duration, delay: 0, easing: 'cubic-bezier(0.16, 1, 0.3, 1)' }, false));
    }
    await Promise.all(runs);
  }

  async _out(skip) {
    this._step = undefined;
    if (!this._visible) return;
    this._visible = false;
    var tl = this._timeline();
    await this._playSegment(tl.out, tl.duration, skip);
    if (this._visible) return;
    this._stage.classList.remove('on');
  }

  /**
   * Runs one animation; resolves when done. fill 'both' (delayed parts hold their first frame), never hangs
   * (browsers pause animations in hidden pages: a timer finishes it), hidden pages skip animation.
   */
  _run(el, keyframes, opts, skip) {
    var instant = skip || document.visibilityState === 'hidden';
    var duration = instant ? 0 : opts.duration;
    var delay = instant ? 0 : (opts.delay || 0);
    var a = el.animate(keyframes, { duration: duration, delay: delay, easing: opts.easing, fill: 'both' });
    var anims = this._anims;
    anims.add(a);
    var timer = new Promise(function (r) { setTimeout(r, delay + duration + 120); });
    return Promise.race([a.finished, timer]).then(function () {
      if (a.playState === 'idle') return;
      if (a.playState !== 'finished') { try { a.finish(); } catch (e) { /* ignore */ } }
      try { a.commitStyles(); } catch (e) { /* not rendered */ }
      a.cancel();
    }, function () {}).finally(function () { anims.delete(a); });
  }

  _cancelAll() {
    this._anims.forEach(function (a) {
      try { a.commitStyles(); } catch (e) { /* ignore */ }
      a.cancel();
    });
    this._anims.clear();
  }
}
`;
